(H/'crops.json').write_text(json.dumps({'papers':{k:'papers/'+k+'.pdf'for k in A},'dpi':260,'crops':C},indent=2)+'\n')
(H/'figure-sources.json').write_text(json.dumps(F,indent=2)+'\n')
subprocess.run([sys.executable,str(H.parents[1]/'tools/crop_panels.py'),str(H/'crops.json')],check=True)
